suppressMessages(library(dplyr)); options(width=250,tibble.width=Inf)
setwd("/Users/hanno/Documents/GitHub/german_election_data")
u <- as_tibble(readRDS("data/county_elections/final/county_elec_unharm.rds"))
h <- as_tibble(readRDS("data/county_elections/final/county_elec_harm_21_muni.rds"))
hc <- as_tibble(readRDS("data/county_elections/final/county_elec_harm_21_cty.rds"))
cat(dim(h),dim(hc),"\n")
print(table(nchar(h$ags))); print(sum(substr(h$ags,1,2)!=h$state)); print(sum(substr(h$ags,1,5)!=h$county))
print(h%>%count(ags,election_year)%>%filter(n>1)%>%nrow()); print(hc%>%count(county_code,election_year)%>%filter(n>1)%>%nrow())
print(table(nchar(hc$county_code))); print(sum(substr(hc$county_code,1,2)!=hc$state))
print(h%>%count(state,election_year)%>%group_by(state)%>%summarise(yrs=paste(election_year,"(",n,")",collapse=" ",sep="")))
print(hc%>%count(state,election_year)%>%group_by(state)%>%summarise(yrs=paste(election_year,"(",n,")",collapse=" ",sep="")))
# totals unharm vs harm muni vs cty by state-year
tu <- u%>%group_by(state,election_year)%>%summarise(ev_u=sum(eligible_voters,na.rm=T),vv_u=sum(valid_votes,na.rm=T),nv_u=sum(number_voters,na.rm=T),.groups="drop")
th <- h%>%group_by(state,election_year)%>%summarise(ev_h=sum(eligible_voters,na.rm=T),vv_h=sum(valid_votes,na.rm=T),nv_h=sum(number_voters,na.rm=T),n=n(),.groups="drop")
tc <- hc%>%group_by(state,election_year)%>%summarise(ev_c=sum(eligible_voters,na.rm=T),vv_c=sum(valid_votes,na.rm=T),nv_c=sum(number_voters,na.rm=T),nc=n(),.groups="drop")
t <- tu%>%full_join(th,by=c("state","election_year"))%>%full_join(tc,by=c("state","election_year"))%>%mutate(d_vv_uh=vv_h/vv_u-1,d_vv_hc=vv_c/vv_h-1,d_ev_uh=ev_h/ev_u-1,d_ev_hc=ev_c/ev_h-1,d_nv_uh=nv_h/nv_u-1)
print(t%>%filter(abs(d_vv_uh)>0.005|abs(d_vv_hc)>0.001|abs(d_ev_uh)>0.005|abs(d_ev_hc)>0.001|is.na(vv_h)|is.na(vv_c))%>%select(state,election_year,n,nc,vv_u,vv_h,vv_c,d_vv_uh,d_vv_hc,d_ev_uh,d_ev_hc),n=100)
saveRDS(t,"t_totals.rds")
